import{_ as l,o,c as i,ah as n}from"./chunks/framework.DjU4PSOm.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"오늘 강의 개요","slug":"오늘-강의-개요","link":"#오늘-강의-개요","children":[]},{"level":2,"title":"\\"목적들(ends)\\"의 다수성에서 출발 — 도구적 목적 vs 최종 목적","slug":"목적들-ends-의-다수성에서-출발-—-도구적-목적-vs-최종-목적","link":"#목적들-ends-의-다수성에서-출발-—-도구적-목적-vs-최종-목적","children":[]},{"level":2,"title":"일원론 vs 다원론 재확인","slug":"일원론-vs-다원론-재확인","link":"#일원론-vs-다원론-재확인","children":[]},{"level":2,"title":"완전성(completeness) 논증","slug":"완전성-completeness-논증","link":"#완전성-completeness-논증","children":[{"level":3,"title":"그 자체를 위해 선택됨 — 돈 vs 우정","slug":"그-자체를-위해-선택됨-—-돈-vs-우정","link":"#그-자체를-위해-선택됨-—-돈-vs-우정","children":[]},{"level":3,"title":"세 단계 위계","slug":"세-단계-위계","link":"#세-단계-위계","children":[]},{"level":3,"title":"비대칭성 논증 — 행복이 최고 자리에 오르는 이유","slug":"비대칭성-논증-—-행복이-최고-자리에-오르는-이유","link":"#비대칭성-논증-—-행복이-최고-자리에-오르는-이유","children":[]}]},{"level":2,"title":"자족성(self-sufficiency) 논증","slug":"자족성-self-sufficiency-논증","link":"#자족성-self-sufficiency-논증","children":[{"level":3,"title":"자족성은 고립이 아니다","slug":"자족성은-고립이-아니다","link":"#자족성은-고립이-아니다","children":[]},{"level":3,"title":"자족성의 경계 문제 — 아리스토텔레스가 스스로 인정한 한계","slug":"자족성의-경계-문제-—-아리스토텔레스가-스스로-인정한-한계","link":"#자족성의-경계-문제-—-아리스토텔레스가-스스로-인정한-한계","children":[]},{"level":3,"title":"\\"고립하여 고려할 때(in isolation)\\" — 용어의 이중적 의미에 주의","slug":"고립하여-고려할-때-in-isolation-—-용어의-이중적-의미에-주의","link":"#고립하여-고려할-때-in-isolation-—-용어의-이중적-의미에-주의","children":[]}]},{"level":2,"title":"\\"행복은 목록에 더해지는 항목이 아니다\\" — 가산성(additivity) 논증","slug":"행복은-목록에-더해지는-항목이-아니다-—-가산성-additivity-논증","link":"#행복은-목록에-더해지는-항목이-아니다-—-가산성-additivity-논증","children":[]},{"level":2,"title":"결론: 행복의 형식적 조건 3가지","slug":"결론-행복의-형식적-조건-3가지","link":"#결론-행복의-형식적-조건-3가지","children":[{"level":3,"title":"핵심 그리스어 개념 정리","slug":"핵심-그리스어-개념-정리","link":"#핵심-그리스어-개념-정리","children":[]}]},{"level":2,"title":"현대적 적용","slug":"현대적-적용","link":"#현대적-적용","children":[]}],"relativePath":"philosophy/Ethics/03. 목적의 완전성과 자족성(에우다이모니아의 형식적 조건).md","filePath":"philosophy/Ethics/03. 목적의 완전성과 자족성(에우다이모니아의 형식적 조건).md"}'),s={name:"philosophy/Ethics/03. 목적의 완전성과 자족성(에우다이모니아의 형식적 조건).md"};function e(r,t,a,u,g,h){return o(),i("div",null,[...t[0]||(t[0]=[n('<h2 id="오늘-강의-개요" tabindex="-1">오늘 강의 개요 <a class="header-anchor" href="#오늘-강의-개요" aria-label="Permalink to &quot;오늘 강의 개요&quot;">​</a></h2><p>지난 시간(1권 7장 정독 전반)에 이어, 아리스토텔레스가 &quot;최종 목적이 하나인가 여럿인가&quot;를 미해결로 남겨둔 지점부터 다시 시작한다. 이번 시간의 목표는 <strong>완전성(completeness)</strong>과 <strong>자족성(self-sufficiency)</strong>이라는 두 형식적 기준을 통해, 왜 에우다이모니아(행복)가 최고선의 자리에 오르는지를 끝까지 따라가는 것이다.</p><p>지난 시간 논증이 도달한 지점과 동일한 결론에 아리스토텔레스는 <strong>다른 경로</strong>로도 도달한다고 말한다 — 1권 2장(욕망의 무한 후퇴 불가능성)과 1권 7장(실천의 구조)이라는 두 개의 서로 다른 논거가 같은 결론을 향해 수렴한다는 것.</p><blockquote><p><strong>정밀성(precision)</strong>의 의미: 아리스토텔레스가 요구하는 &quot;더 정밀한 설명&quot;은 수학적 정확성이 아니다(1권 3장에서 이미 윤리학은 수학만큼 엄밀할 수 없다고 경고). 인간 행위는 상황에 따라 가변적이므로, 여기서 필요한 정밀성은 <strong>개념적 명확성</strong>이다.</p></blockquote><p><strong>왜 텍스트를 문장 단위로 정독하는가</strong>: 철학 텍스트는 한 철학자의 사유를 보여주는 지적 건축물이다. 그 구조를 면밀히 검토함으로써 논증이 어떻게 구성되는지, 개념들이 어떻게 상호 연결되는지, 텍스트 구조에서 어떤 한계와 함의가 나오는지를 이해할 수 있다.</p><h2 id="목적들-ends-의-다수성에서-출발-—-도구적-목적-vs-최종-목적" tabindex="-1">&quot;목적들(ends)&quot;의 다수성에서 출발 — 도구적 목적 vs 최종 목적 <a class="header-anchor" href="#목적들-ends-의-다수성에서-출발-—-도구적-목적-vs-최종-목적" aria-label="Permalink to &quot;&quot;목적들(ends)&quot;의 다수성에서 출발 — 도구적 목적 vs 최종 목적&quot;">​</a></h2><ul><li>아리스토텔레스는 목적(ends)이 여럿임을 인정하는 데서 시작한다: 우리는 부, 과일, 악기(flute) 같은 것들을 <strong>다른 무언가를 위해</strong> 선택한다. 즉 모든 목적이 완전한 것은 아니다.</li><li><strong>도구적(instrumental)</strong> 목적: 다른 목표를 달성하기 위한 수단. 대표 사례는 <strong>부(wealth)</strong> — 자본주의 사회에서 음식·주거·교육·돌봄·교통 등과 교환할 수 있기 때문에 유용하지만, 그 자체가 목적은 아니다.</li><li>플루트·의료 기구 같은 도구도 마찬가지로 그것이 봉사하는 활동(연주, 진단·치료)을 위해 선택된다.</li><li><strong>중요한 해명</strong>: 도구적 선이라고 해서 무가치한 것은 아니다. 돈·도구·자격은 사회에서 매우 중요할 수 있다. 요점은 그 <strong>가치가 그것이 해결하는 목적에 달려 있다</strong>는 것 — 예컨대 대학 학위는 진정한 선이지만, 그 가치가 자기 자신을 넘어선 곳(취업 → 고소득 → 안정)을 향하기 때문에 &quot;완전한&quot; 선은 아니다. <ul><li>토론 질문: 도구적 선이 너무 중요해져서 사람들이 그것을 삶의 최종 목적으로 착각할 수 있는가?</li></ul></li></ul><h2 id="일원론-vs-다원론-재확인" tabindex="-1">일원론 vs 다원론 재확인 <a class="header-anchor" href="#일원론-vs-다원론-재확인" aria-label="Permalink to &quot;일원론 vs 다원론 재확인&quot;">​</a></h2><p>지난 시간 다룬 구도를 다시 짚는다.</p><ul><li><strong>일원론(monism)</strong>: 세계를 구조 짓는 원리가 오직 하나.</li><li><strong>이원론(dualism)</strong>: 두 개의 뚜렷한 원리.</li><li><strong>다원론(pluralism)</strong>: 여러 원리가 공존.</li></ul><p>아리스토텔레스가 &quot;만약 하나의 완전한 목적이 있다면 그것이 우리가 찾는 것이고, 여럿이 있다면 그중 가장 완전한 것이 그것&quot;이라고 조건문으로 말할 때, 그는 <strong>가치 있는 것이 정확히 하나여야 한다고 주장하는 게 아니다</strong> — 우정도, 지식도 그 자체로 가치 있을 수 있음을 허용한다. 다만 다음 질문이 남는다: <strong>이 선들 중 하나가 다른 것들보다 더 완전한 삶의 조직을 제공하는가?</strong></p><ul><li><strong>complete(완전한 것)</strong>: 수단이 아니라 그 자체를 위해 선택됨.</li><li><strong>the most complete(가장 완전한 것)</strong>: 그 자체를 위해 선택될 뿐 아니라, 다른 자기-선택적 선들보다도 더 최종적이고 포괄적임.</li><li><strong>해석적 쟁점</strong> (아직 미해결): 행복은 다른 선들 위에 군림하는 <strong>하나의 지배적 활동</strong>인가, 아니면 우정·덕·쾌락·지식 같은 <strong>여러 선을 포함·조직하는 것</strong>인가?</li></ul><h2 id="완전성-completeness-논증" tabindex="-1">완전성(completeness) 논증 <a class="header-anchor" href="#완전성-completeness-논증" aria-label="Permalink to &quot;완전성(completeness) 논증&quot;">​</a></h2><h3 id="그-자체를-위해-선택됨-—-돈-vs-우정" tabindex="-1">그 자체를 위해 선택됨 — 돈 vs 우정 <a class="header-anchor" href="#그-자체를-위해-선택됨-—-돈-vs-우정" aria-label="Permalink to &quot;그 자체를 위해 선택됨 — 돈 vs 우정&quot;">​</a></h3><ul><li>돈은 보통 다른 것을 얻기 위한 수단으로 선택된다. 반면 <strong>진정한 우정</strong>은 도구로서만 가치 있게 여겨지지 않는다 — 우리는 관계 그 자체를 소중히 여긴다. 그래서 우정이 돈보다 &quot;더 완전&quot;하다.</li><li><strong>주의</strong>: 완전성은 유용성의 척도가 아니다 — 우정이 항상 돈보다 유용하다는 뜻이 아니라, <strong>얼마나 독립적으로 선택할 가치가 있는가</strong>를 재는 척도다.</li><li><strong>&quot;그 자체로 선택됨&quot;의 의미</strong>: 그 가치가 별도의 외적 보상이 없어도 사라지지 않는다는 것. 예: 학위만을 위해 철학을 공부하는 학생과, 소득으로 이어지지 않아도 이해 자체를 소중히 여기는 학생 — 후자가 이해를 더 완전한 것으로 대우하는 것. <ul><li>토론 질문: 외적 보상이 전혀 없어도 계속 가치 있게 여길 활동은 무엇인가?</li></ul></li></ul><h3 id="세-단계-위계" tabindex="-1">세 단계 위계 <a class="header-anchor" href="#세-단계-위계" aria-label="Permalink to &quot;세 단계 위계&quot;">​</a></h3><ol><li><strong>순수하게 도구적</strong> — 오직 다른 것을 위해서만 선택됨. 대표 사례: 돈.</li><li><strong>그 자체를 위해서 + 행복을 위해서</strong> 둘 다 선택됨 — 명예(honor), 쾌락(pleasure), 지성(intelligence), 덕(virtue/excellence).</li><li><strong>오직 그 자체를 위해서만</strong> 선택되고 결코 다른 것을 위해서는 아님 — <strong>행복(에우다이모니아)</strong>.</li></ol><p>최고선은 반드시 3단계에 속해야 한다. 이는 명예·쾌락·지성·덕의 내재적 가치를 부정하는 것이 아니라, 사람들이 이것들을 행복의 <strong>일부 또는 원인</strong>으로도 추구한다는 사실을 지적하는 것이다.</p><ul><li><strong>명예</strong>: 타인의 승인에 의존해 불안정하지만, 우리는 칭찬받길 원하고 비난받길 꺼린다.</li><li><strong>쾌락</strong>: 그 자체로 직접 가치 있게 여겨짐 — 추가 이유가 필요 없다.</li><li><strong>지성</strong>: 지성이나 이해로 환원되지 않는 독자적 가치.</li><li><strong>덕(탁월성)</strong>: 아리스토텔레스는 나중에 행복을 &quot;덕에 따른 활동&quot;으로 정의할 것이므로, 덕은 돈처럼 단순 외적 도구가 아니라 <strong>행복을 구성하는(constitutive)</strong> 요소에 가깝다. <ul><li>지성만으로는 함께 번영하는 삶을 보장하지 않는다 — 지성은 조작·착취·파괴에도 쓰일 수 있기 때문에, 그 가치는 <strong>성격과 어떻게 통합되어 발휘되는가</strong>에 달려 있다.</li></ul></li></ul><h3 id="비대칭성-논증-—-행복이-최고-자리에-오르는-이유" tabindex="-1">비대칭성 논증 — 행복이 최고 자리에 오르는 이유 <a class="header-anchor" href="#비대칭성-논증-—-행복이-최고-자리에-오르는-이유" aria-label="Permalink to &quot;비대칭성 논증 — 행복이 최고 자리에 오르는 이유&quot;">​</a></h3><blockquote><p>&quot;명예·쾌락·지성·덕은 그 자체를 위해서도 선택하지만 행복을 위해서도 선택한다. 그러나 행복은 결코 다른 무언가를 위해 선택하지 않는다.&quot;</p></blockquote><ul><li>관계는 <strong>비대칭적</strong>이다: 우리는 덕·쾌락·지성·명예를 부분적으로는 행복을 위해 선택하지만, 행복을 그것들을 얻기 위한 <strong>수단으로</strong> 선택하지는 않는다.</li><li>논증 구조: 어떤 선은 오직 다른 것을 위해서만 선택됨(돈) → 어떤 선은 그 자체와 행복 둘 다를 위해 선택됨(덕·지성·쾌락·명예) → 행복은 오직 그 자체를 위해서만 선택됨 → 그러므로 행복이 가장 높은, 가장 완전한 목적이다.</li><li><strong>비판적 검토</strong>: 이 논증은 &quot;사람들이 실제로 어떻게 선택하는가&quot;라는 경험적 전제에 의존한다. 모든 사람이 정말 같은 방식으로 행복을 선택하는가? 누군가는 행복해지지 않더라도 도덕적 의무를 추구하거나, 정의·종교·가족·정치적 헌신을 위해 행복을 희생하기도 한다(예: 일제강점기 독립운동가들의 희생). 아리스토텔레스라면 이런 헌신도 에우다이모니아가 <strong>경쟁하는 것이 아니라 포함하거나 의미를 부여하는 것</strong>이라고 답할 가능성이 크다. <ul><li>토론 질문: 한 사람이 타인을 위한 정의를 위해 자신의 행복을 합리적으로 희생할 수 있는가?</li></ul></li></ul><h2 id="자족성-self-sufficiency-논증" tabindex="-1">자족성(self-sufficiency) 논증 <a class="header-anchor" href="#자족성-self-sufficiency-논증" aria-label="Permalink to &quot;자족성(self-sufficiency) 논증&quot;">​</a></h2><p>완전성과 별개로, 최고선을 식별하는 <strong>두 번째 형식적 기준</strong>이 자족성이다.</p><ul><li><strong>완전성</strong>은 선택의 구조(그 자체를 위해 선택되는가)에 관한 것.</li><li><strong>자족성</strong>은 그 선을 포함하는 <strong>삶의 질</strong>(본질적 결핍 없이 삶을 선택할 가치 있게 만드는가)에 관한 것. 서로 관련되지만 동일하지는 않다.</li></ul><h3 id="자족성은-고립이-아니다" tabindex="-1">자족성은 고립이 아니다 <a class="header-anchor" href="#자족성은-고립이-아니다" aria-label="Permalink to &quot;자족성은 고립이 아니다&quot;">​</a></h3><blockquote><p>&quot;자족적이란 혼자 사는 사람에게 충분하다는 뜻이 아니라, 부모·자녀·배우자, 일반적으로 사랑하는 사람들과 동료 시민들에게까지 충분하다는 뜻이다 — 인간은 본성상 <strong>시민적 존재(정치적 동물, zōon politikon)</strong>이기 때문이다.&quot;</p></blockquote><ul><li>자족적인 삶은 고립된 개인의 삶이 아니다 — 가족, 사랑하는 사람, 동료 시민을 포함한다. 인간은 본성적으로 정치 공동체 속에서 산다.</li><li><strong>자족성 ≠ 원자론적 개인주의</strong>: 상업 사회의 개인주의와 아리스토텔레스적 자족성을 혼동하면 안 된다. 인간은 언어·교육·우정·협력·정치 제도라는 공동체적 조건 안에서만 자신의 능력을 발전·행사한다 — 언어조차 개인이 발명한 것이 아니라 물려받은 유산이다.</li><li><strong>&quot;정치적 동물(political animal)&quot; 번역에 대한 주석</strong>: 단순히 물리적으로 가까이 산다는 뜻이 아니라, 인간이 언어·법·판단·제도를 통해 <strong>공동의 삶을 조직</strong>한다는 뜻. (원문의 &quot;아내&quot;라는 표현은 아리스토텔레스 당대의 남성 가장 중심 시각을 반영하므로, 현대적 재구성에서는 가족·동반자 관계·돌봄의 다양한 형태로 확장해서 읽어야 한다.)</li><li><strong>현대적 함의</strong>: &quot;자수성가(self-made)&quot;라는 신화와 달리, 누구도 문자 그대로 자기 힘만으로 만들어지지 않는다 — 공교육, 인프라(도로·인터넷·전력망), 돌봄 제공자, 사회적 신뢰, 정치적 안정에 의존한다. 자율성은 고립이 아니라 <strong>관계적으로 지지되는 것</strong>으로 이해해야 한다. <ul><li>토론 질문: 타인에 대한 의존은 자율성을 약화시키는가, 아니면 자율성을 가능하게 하는 조건 중 하나인가?</li></ul></li></ul><h3 id="자족성의-경계-문제-—-아리스토텔레스가-스스로-인정한-한계" tabindex="-1">자족성의 경계 문제 — 아리스토텔레스가 스스로 인정한 한계 <a class="header-anchor" href="#자족성의-경계-문제-—-아리스토텔레스가-스스로-인정한-한계" aria-label="Permalink to &quot;자족성의 경계 문제 — 아리스토텔레스가 스스로 인정한 한계&quot;">​</a></h3><ul><li>만약 &quot;행복에 포함되는 관계의 범위&quot;를 계속 확장하면(자녀 → 자녀의 자녀 → 친구의 친구 → 먼 후손...) <strong>무한 후퇴</strong>에 빠진다. 그래서 &quot;어딘가에 한계가 있어야 한다&quot;고 말하지만, <strong>아리스토텔레스는 여기서 그 한계를 제시하지 않고 &quot;다른 기회에 살펴보겠다&quot;며 논의를 미룬다.</strong></li><li>이는 해결이 아니라 <strong>의도적 유예(deliberate suspension)</strong>다 — 아리스토텔레스는 종종 모든 연결된 문제를 한 번에 다루지 않고 하나를 분리해 논의를 진전시킨다. 우정·가족·시민권에 관한 후속 논의가 자원을 제공하긴 하지만, 그가 이 경계 문제를 명시적으로 완전히 해결한다고 선언하지는 않는다.</li><li><strong>방법론적 교훈</strong>: 독자는 세 가지를 구별해야 한다 — (1) 아리스토텔레스가 인식한 문제, (2) 그가 실제로 제공한 해법, (3) 후대 해석자들이 체계적으로 구성한 해법. 이 셋을 혼동하면 안 된다.</li><li>이 문제는 현대 글로벌 윤리학에서도 반복된다: 우리의 책임은 가족을 넘어 동료 시민, 낯선 사람, 미래 세대, 비인간 존재에게까지 어디까지 확장되는가? <ul><li>토론 질문: 문제를 미루는 것은 철학적으로 정당한 전략인가, 아니면 자족성 논증 자체를 약화시키는가?</li></ul></li></ul><h3 id="고립하여-고려할-때-in-isolation-—-용어의-이중적-의미에-주의" tabindex="-1">&quot;고립하여 고려할 때(in isolation)&quot; — 용어의 이중적 의미에 주의 <a class="header-anchor" href="#고립하여-고려할-때-in-isolation-—-용어의-이중적-의미에-주의" aria-label="Permalink to &quot;&quot;고립하여 고려할 때(in isolation)&quot; — 용어의 이중적 의미에 주의&quot;">​</a></h3><p>이 구절은 두 가지로 오독하기 쉽다.</p><ol><li><strong>잘못된 독해</strong>: &quot;행복한 사람은 고립된(isolated) 삶을 산다&quot; — 이는 바로 앞 문장(가족·친구·시민 포함)과 모순되므로 틀렸다.</li><li><strong>올바른 독해</strong>: &quot;그 자체만 떼어놓고(considered by itself, in isolation) 평가했을 때&quot; — 즉 행복이 다른 어떤 궁극선을 추가로 요구하지 않고도 그 자체로 삶을 바람직하게 만들기에 충분한가를 묻는 것.</li></ol><p>또한 &quot;<strong>아무것도 결핍되지 않음(lacking in nothing)</strong>&quot;이 &quot;모든 가능한 선을 문자 그대로 다 가짐&quot;을 뜻하는 것도 아니다 — 아리스토텔레스는 이후 행복이 일정한 외부적 선(건강, 우호적 환경 등)을 필요로 하며 불운에 취약할 수 있음을 인정한다. 이 구절의 정확한 의미는 <strong>인간적 삶으로서 선택하는 데 본질적인 것이 결핍되지 않음</strong>이다.</p><ul><li>토론 질문: 자족성이란 모든 중요한 선을 소유하는 것을 뜻하는가, 아니면 신뢰할 만한 삶에 필수적인 것만 소유하는 것을 뜻하는가?</li></ul><h2 id="행복은-목록에-더해지는-항목이-아니다-—-가산성-additivity-논증" tabindex="-1">&quot;행복은 목록에 더해지는 항목이 아니다&quot; — 가산성(additivity) 논증 <a class="header-anchor" href="#행복은-목록에-더해지는-항목이-아니다-—-가산성-additivity-논증" aria-label="Permalink to &quot;&quot;행복은 목록에 더해지는 항목이 아니다&quot; — 가산성(additivity) 논증&quot;">​</a></h2><blockquote><p>&quot;만약 행복이 다른 선들의 목록에 포함되는 항목이었다면, 거기에 무언가를 더 보태는 순간 그 전체가 더 바람직해졌을 것이다 — 더해진 것은 언제나 재화의 양을 늘리고, 더 큰 총량은 언제나 더 바람직하기 때문이다.&quot;</p></blockquote><ul><li>논증 구조: 행복이 가장 바람직한 선이라고 가정 → 만약 행복이 다른 선들과 함께 <strong>더해질 수 있는 하나의 평범한 항목</strong>이라면 → 행복 + 아주 작은 다른 선을 더한 것이 행복 단독보다 더 바람직해질 것 → 이는 &quot;행복이 이미 가장 바람직한 선&quot;이라는 전제와 모순 → <strong>따라서 행복은 다른 선들과 단순히 합산되는 독립적 항목일 수 없다.</strong></li><li><strong>주의</strong>: 이것이 곧바로 &quot;행복이 다른 모든 선과 완전히 다른 논리적 범주에 속한다&quot;는 것을 증명하지는 않는다 — 오히려 행복이 <strong>다른 선들을 포함하고 완성하는 것</strong>이라는 해석을 시사할 수도 있다. 예컨대 소득·건강·우정·노동·인정의 목록이 있을 때, 행복은 그 목록에 추가되는 또 하나의 항목이 아니라 <strong>그 목록 전체가 가치 있는 삶으로 어떻게 조직되는지를 설명하는 것</strong>일 수 있다.</li><li>이 지점에서도 텍스트는 &quot;행복 = 하나의 지배적 활동인가, 여러 선의 총체적 조직인가&quot;라는 질문을 결정적으로 해소하지 않은 채 남겨둔다. <ul><li>토론 질문: 행복은 별개의 선인가, 여러 선의 집합인가, 아니면 서로 다른 선들을 하나의 삶으로 조직하는 형식인가?</li></ul></li></ul><h2 id="결론-행복의-형식적-조건-3가지" tabindex="-1">결론: 행복의 형식적 조건 3가지 <a class="header-anchor" href="#결론-행복의-형식적-조건-3가지" aria-label="Permalink to &quot;결론: 행복의 형식적 조건 3가지&quot;">​</a></h2><blockquote><p>&quot;그러므로 행복은 분명히 완전하고 자족적인 것으로서, 우리의 실천적 활동이 향하는 목적(end)이다.&quot;</p></blockquote><p>아리스토텔레스는 세 가지 이전 논증을 하나로 묶어 결론짓는다.</p><ol><li><strong>행복은 더 나아간 다른 무언가를 위해 선택되지 않는다</strong> (완전성/finality).</li><li><strong>행복은 삶을 선택할 가치 있게 만들고, 본질적으로 결핍된 것이 없게 한다</strong> (자족성).</li><li><strong>행복은 인간의 행동과 선택에 최종적 방향을 부여한다.</strong></li></ol><p>단, 이 시점에서 아리스토텔레스는 <strong>행복의 형식적 구조만</strong> 설명했을 뿐, 행복이 구체적으로 <strong>어떤 종류의 활동인지는 아직 설명하지 않았다.</strong> 이 때문에 논의는 곧바로 다음 문제로 넘어간다: &quot;최고선이 충족해야 할 형식적 조건&quot;에서 &quot;그 조건을 실제로 충족하는 실질적 활동은 무엇인가&quot;로 — 이것이 다음 시간에 다룰 <strong>기능 논증(function argument)</strong>으로 이어진다.</p><h3 id="핵심-그리스어-개념-정리" tabindex="-1">핵심 그리스어 개념 정리 <a class="header-anchor" href="#핵심-그리스어-개념-정리" aria-label="Permalink to &quot;핵심 그리스어 개념 정리&quot;">​</a></h3><ul><li><strong>아가톤(agathon)</strong>: 모든 행위·기술·선택이 목표로 하는 선.</li><li><strong>텔로스(telos)</strong>: 어떤 행위가 그것을 위해 수행되는 목적.</li><li><strong>텔레이온(teleion)</strong>: 완전함 — 오로지 그 자체를 위해 선택되고 결코 다른 것의 수단이 아님.</li><li><strong>에우다이모니아(eudaimonia)</strong>: 궁극적 인간선. 언제나 그 자체를 위해 선택되며 결코 다른 목적을 위해서는 아님. 단순한 쾌락 경험이 아니라 <strong>잘 살고 번영하는 것</strong>을 가리킴.</li><li><strong>아우타르케이아(autarkeia, 자족)</strong>: 삶을 완전히 바람직하게 만들고 본질적 결핍이 없게 하는 성질.</li></ul><h2 id="현대적-적용" tabindex="-1">현대적 적용 <a class="header-anchor" href="#현대적-적용" aria-label="Permalink to &quot;현대적 적용&quot;">​</a></h2><p>현대 소비문화는 종종 돈·사회적 지위·소유물·생산성 같은 <strong>도구적 선</strong>을 마치 궁극 목적인 것처럼 추구하도록 부추긴다. 아리스토텔레스적 물음은 이런 목표들이 실제로 살 가치가 있는 삶에 기여하는지, 아니면 잊혀진 목적을 위한 수단으로만 기능하는지를 묻게 한다. 지속가능성·공공정책·삶의 질에 관한 현대적 논의가 경제적 번영과 인간적 번영을 구분하는 것도 이와 같은 맥락이며, 에우다이모니아 개념은 부(wealth)뿐 아니라 건강·교육·의미 있는 우정·시민 참여·생태적 조건으로 사회를 평가하는 오늘날의 접근을 이미 예견하고 있다.</p><hr><p><em>출처: KNU Canvas TransLive 실시간 통번역 자막(2026-09-14, 윤리학 001분반 2주차 두 번째 시간, 윤지영 교수) 및 강의 자료를 바탕으로 직접 재구성한 정리 노트. 원문 자막 전문은 <a href="./Raw-Transcripts/2026-09-14_week2-2.html">Raw-Transcripts 폴더</a>에 별도 보관.</em></p>',49)])])}const d=l(s,[["render",e]]);export{q as __pageData,d as default};
